```python
phone_now = apis.phone.get_current_date_and_time()
month_names = ["january", "february", "march", "april", "may", "june", "july", "august", "september", "october", "november", "december"]
date_text = phone_now["date"].strip()
date_lower = date_text.lower()
digit_tokens = "".join(ch if ch.isdigit() else " " for ch in date_text).split()
current_year = None
year_position = None
for index, token in enumerate(digit_tokens):
    if len(token) == 4:
        current_year = int(token)
        year_position = index
        break
current_month_number = None
for index, month_name in enumerate(month_names):
    if month_name in date_lower or month_name[:3] in date_lower:
        current_month_number = index + 1
        break
if current_month_number is None and year_position is not None:
    numeric_parts = [int(token) for token in digit_tokens]
    if year_position == 0 and len(numeric_parts) > 1:
        current_month_number = numeric_parts[1]
    elif year_position > 0:
        preceding = numeric_parts[:year_position]
        if len(preceding) >= 2:
            current_month_number = preceding[1] if preceding[0] > 12 else preceding[0]
        elif preceding:
            current_month_number = preceding[0]
if current_year is None or current_month_number not in range(1, 13):
    raise RuntimeError("Could not derive the current calendar month from the phone date")
if current_month_number == 1:
    last_month_number = 12
    last_month_year = current_year - 1
else:
    last_month_number = current_month_number - 1
    last_month_year = current_year
last_month_name = month_names[last_month_number - 1]
