Read every candidate file, rank candidates using internet, receipt, and prior-month evidence, and extract the best positively identified monetary total from the selected receipt.

```python
if not receipt_path_candidates:
    raise RuntimeError("No candidate receipt files were found")
receipt_files = []
for file_path in receipt_path_candidates:
    receipt_files.append(apis.file_system.show_file(file_path=file_path, access_token=file_system_access_token))

def receipt_relevance(file_record):
    searchable = "\n".join([file_record.get("path", ""), file_record.get("content", ""), file_record.get("created_at", ""), file_record.get("updated_at", "")]).lower()
    score = 0
    if "internet" in searchable:
        score += 100
    if "bill" in searchable:
        score += 15
    if "receipt" in searchable:
        score += 15
    if "paid" in searchable:
        score += 10
    prior_month_patterns = [
        last_month_name,
        last_month_name[:3],
        f"{last_month_year}-{last_month_number:02d}",
        f"{last_month_number:02d}/{last_month_year}",
        f"{last_month_number}/{last_month_year}",
        f"{last_month_number:02d}-{last_month_year}",
    ]
    if any(pattern in searchable for pattern in prior_month_patterns):
        score += 50
    if str(last_month_year) in searchable:
        score += 5
    return score

def extract_number_tokens(text):
    results = []
    start = None
    for position, character in enumerate(text + " "):
        if character.isdigit() or (start is not None and character in ",."):
            if start is None:
                start = position
        elif start is not None:
            raw = text[start:position].strip(".,")
            normalized = raw.replace(",", "")
            if normalized and normalized.count(".") <= 1 and any(ch.isdigit() for ch in normalized):
                try:
                    value = float(normalized)
                except ValueError:
                    value = None
                if value is not None and value > 0:
                    results.append((value, start, position, raw))
            start = None
    return results

def derive_bill_total(file_record):
    candidates = []
    for line_index, line in enumerate(file_record.get("content", "").splitlines()):
        lowered = line.lower()
        if "amount paid" in lowered or "total paid" in lowered or "balance paid" in lowered:
            label_score = 70
        elif "grand total" in lowered or "total amount" in lowered or "bill total" in lowered:
            label_score = 65
        elif "total" in lowered:
            label_score = 50
        elif "amount" in lowered:
            label_score = 30
        elif "paid" in lowered or "balance" in lowered or "due" in lowered:
            label_score = 20
        else:
            label_score = 0
        for value, start, end, raw in extract_number_tokens(line):
            before = lowered[max(0, start - 6):start]
            after = lowered[end:end + 6]
            currency_marked = "$" in before or "usd" in before or "usd" in after
            score = label_score + (40 if currency_marked else 0)
            if "." in raw and len(raw.rsplit(".", 1)[-1]) == 2:
                score += 3
            if value in [float(current_year), float(last_month_year)]:
                score -= 40
            if "%" in after:
                score -= 40
            if score > 0:
                candidates.append({"value": value, "score": score, "currency_marked": currency_marked, "line_index": line_index})
    if not candidates:
        raise RuntimeError("No positively identified bill amount was found in the selected receipt")
    best = max(candidates, key=lambda candidate: (candidate["score"], candidate["currency_marked"], candidate["value"]))
    return best["value"], candidates

receipt_rankings = [{"file": record, "score": receipt_relevance(record)} for record in receipt_files]
selected_receipt = max(receipt_rankings, key=lambda item: (item["score"], item["file"]["path"]))["file"]
bill_total, bill_amount_candidates = derive_bill_total(selected_receipt)
print({"file_candidate_scores": [{"path": item["file"]["path"], "score": item["score"]} for item in receipt_rankings], "selected_receipt": selected_receipt["path"], "derived_bill_total": bill_total})
